export default function Section() {
  return (
    <section className="bg-primary-50 text-secondary-900 border-b-4 border-secondary-900">
      <div className="border-b-2 border-secondary-900 bg-surface">
        <nav aria-label="Breadcrumb" className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
          <Breadcrumbs className="flex flex-wrap items-center gap-x-2 gap-y-1 py-3 font-mono text-sm uppercase tracking-wider">
            {(c) =>
              c.current ? (
                <span aria-current="page" className="inline-flex min-h-11 items-center bg-secondary-900 px-2 font-bold text-white">
                  {c.name}
                </span>
              ) : (
                <span className="inline-flex items-center gap-2">
                  <Link href={c.url} className="inline-flex min-h-11 items-center underline decoration-2 underline-offset-4 hover:bg-accent-500">
                    {c.name}
                  </Link>
                  <span aria-hidden="true" className="font-bold text-foreground-muted">/</span>
                </span>
              )
            }
          </Breadcrumbs>
        </nav>
      </div>

      <Brand>
        {(b) => (
          <div className="mx-auto max-w-7xl px-4 py-10 sm:px-6 md:py-16 lg:px-8">
            <div className="grid grid-cols-1 gap-10 lg:grid-cols-12 lg:gap-12">
              {/* Heavy box: logo and name */}
              <div className="lg:col-span-5">
                <div className="relative mr-2 mb-2">
                  <div aria-hidden="true" className="absolute inset-0 translate-x-2 translate-y-2 bg-secondary-900" />
                  <div className="relative border-4 border-secondary-900 bg-primary-500 text-secondary-900">
                    <div className="flex items-center justify-between border-b-4 border-secondary-900 bg-secondary-900 px-4 py-2 font-mono text-xs uppercase tracking-widest text-white">
                      <span>The maker</span>
                      <span className="text-accent-500">●</span>
                    </div>
                    <div className="p-5 sm:p-8">
                      <div className="w-32 border-4 border-secondary-900 bg-white sm:w-40">
                        {b.logo ? (
                          <Image src={b.logo} alt={b.name} aspect="1:1" fit="contain" sizes="160px" priority />
                        ) : (
                          <div className="flex aspect-square items-center justify-center bg-accent-500">
                            <Icon name="badge-check" size="xl" className="text-secondary-900" strokeWidth={2} />
                          </div>
                        )}
                      </div>
                      <h1 className="mt-6 break-words font-display text-3xl font-bold uppercase leading-none sm:text-5xl">
                        {b.name}
                      </h1>
                      {b.productCount > 0 && (
                        <p className="mt-4 inline-flex items-center gap-2 border-2 border-secondary-900 bg-white px-3 py-1 font-mono text-sm uppercase tracking-wider">
                          <Icon name="boxes" size="sm" className="text-secondary-900" />
                          {b.productCount} products
                        </p>
                      )}
                    </div>
                  </div>
                </div>
              </div>

              {/* Words */}
              <div className="flex flex-col gap-8 lg:col-span-7">
                {b.tagline && (
                  <p className="font-display text-2xl font-bold uppercase leading-tight sm:text-3xl">
                    <span className="bg-accent-500 box-decoration-clone px-1">{b.tagline}</span>
                  </p>
                )}

                {(b.story || b.description) && (
                  <div className="border-l-4 border-secondary-900 pl-4 sm:pl-6">
                    <p className="font-mono text-xs uppercase tracking-widest text-foreground-muted">Who makes it</p>
                    <p className="mt-3 whitespace-pre-line text-base leading-relaxed text-secondary-900 sm:text-lg">
                      {b.story || b.description}
                    </p>
                  </div>
                )}

                {(b.founded || b.origin || b.headquarters) && (
                  <dl className="grid grid-cols-1 gap-0.5 border-2 border-secondary-900 bg-secondary-900 sm:grid-cols-3">
                    {b.founded && (
                      <div className="bg-surface p-4">
                        <dt className="font-mono text-xs uppercase tracking-widest text-foreground-muted">Since</dt>
                        <dd className="mt-1 font-display text-xl font-bold uppercase">{b.founded}</dd>
                      </div>
                    )}
                    {b.origin && (
                      <div className="bg-surface p-4">
                        <dt className="font-mono text-xs uppercase tracking-widest text-foreground-muted">Origin</dt>
                        <dd className="mt-1 font-display text-xl font-bold uppercase break-words">{b.origin}</dd>
                      </div>
                    )}
                    {b.headquarters && (
                      <div className="bg-surface p-4">
                        <dt className="font-mono text-xs uppercase tracking-widest text-foreground-muted">Based in</dt>
                        <dd className="mt-1 font-display text-xl font-bold uppercase break-words">{b.headquarters}</dd>
                      </div>
                    )}
                  </dl>
                )}

                {(b.website || b.socials.length > 0) && (
                  <div className="flex flex-wrap items-center gap-3">
                    {b.website && (
                      <Link
                        href={b.website}
                        target="_blank"
                        className="inline-flex min-h-11 items-center gap-2 border-2 border-secondary-900 bg-secondary-900 px-5 font-mono text-sm font-bold uppercase tracking-wider text-white hover:bg-primary-500 hover:text-secondary-900"
                      >
                        Visit website
                        <Icon name="arrow-up-right" size="sm" />
                      </Link>
                    )}
                    {b.socials.map((s, i) => (
                      <Link
                        key={i}
                        href={s.href}
                        target="_blank"
                        className="inline-flex min-h-11 items-center border-2 border-secondary-900 bg-white px-4 font-mono text-sm uppercase tracking-wider text-secondary-900 hover:bg-accent-500"
                      >
                        {s.label}
                      </Link>
                    ))}
                  </div>
                )}

                {b.image && (
                  <div className="border-4 border-secondary-900 bg-white">
                    <Image
                      src={b.image}
                      alt={b.name}
                      aspect="21:9"
                      fit="cover"
                      sizes="(min-width: 1024px) 55vw, 100vw"
                    />
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </Brand>
    </section>
  )
}
